 "content": "from functools import lru_cache

def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8}
    if not cells:
        return [[0] * w for _ in range(h)]

    # Tile the figure with 2x2 squares and L-triominoes. Prefer the most
    # 2x2 squares; the remaining pieces are oriented Ls.
    placements = []
    for r in range(h - 1):
        for c in range(w - 1):
            block = {(r, c), (r+1, c), (r, c+1), (r+1, c+1)}
            if block <= cells:
                placements.append((block, 1, -1))
            for missing, color in [((r,c), 2), ((r+1,c), 3), ((r,c+1), 4), ((r+1,c+1), 5)]:
                tri = block - {missing}
                if tri <= cells:
                    placements.append((tri, color, -1))

    by_cell = {p: [] for p in cells}
    for item in placements:
        shape = item[0]
        for p in shape:
            by_cell[p].append(item)
    # Choose the most constrained uncovered cell, searching square pieces first.
    def key(item):
        shape, color, _ = item
        return (0 if color == 1 else 1, -len(shape), min(shape))

    @lru_cache(None)
    def solve(remaining):
        remaining = frozenset(remaining)
        if not remaining:
            return ()
        p = min(remaining, key=lambda q: (sum(1 for item in by_cell[q] if item[0] <= remaining), q))
        options = sorted((item for item in by_cell[p] if item[0] <= remaining), key=key)
        for item in options:
            rest = solve(frozenset(remaining - item[0]))
            if rest is not None:
                return (item,) + rest
        return None

    tiling = solve(frozenset(cells))
    if tiling is None:
        raise ValueError('Input cannot be tiled by 2x2 squares and L-triominoes')
    # Among exact tilings, the search favors squares; assign the corresponding
    # orientation color to each L (missing TL=2, BL=3, TR=4, BR=5).
    out = [[0] * w for _ in range(h)]
    for shape, color, _ in tiling:
        for r, c in shape:
            out[r][c] = color
    return out
